<div class="d-flex justify-content-between mb-3"><h2 class="fw-bold">Approvisionnements</h2><a class="btn btn-km" href="<?=e(base_url('purchases/create'))?>">+ Bon de commande</a></div><div class="km-card p-3"><div class="table-responsive"><table class="table"><thead><tr><th>N°</th><th>Fournisseur</th><th>Date</th><th>Total</th><th>Statut</th><th></th></tr></thead><tbody><?php foreach($orders as $o):?><tr><td><?=e($o['order_no'])?></td><td><?=e($o['company_name'])?></td><td><?=e($o['created_at'])?></td><td><?=money($o['total'])?></td><td><?=e($o['status'])?></td><td class="text-end"><?php if(in_array($o['status'],['COMMANDE','PARTIELLEMENT_RECU'])):?><form method="post" action="<?=e(base_url('purchases/'.$o['id'].'/receive'))?>" class="d-inline"><?=csrf_field()?><button class="btn btn-sm btn-km" data-confirm="Confirmer la réception complète et augmenter le stock ?">Réceptionner</button></form><?php endif;?></td></tr><?php endforeach;?></tbody></table></div></div>